<?php require_once __DIR__ . '/icons.php'; $listFilter=$deliverySearch['filter'] ?? 'pending'; $isHistory=$listFilter==='approved'; $listPage='deliveries'; $pendingOnly=$listFilter==='pending'; $filter='&amp;f=' . $listFilter; $isAdmin=($_SESSION['admin_role'] ?? 'admin')==='admin';
// Tarjetas de estado: filtran la tabla y cuentan las solicitudes de la búsqueda actual. [filtro, título, detalle, ícono].
$statusCards=[['pending','Pendientes','Pdt. por gestionar','clock'],['approved','Aprobadas','Listas o enviadas','check-circle'],['not_registered','No registra','Sin registro clínico','file-x'],['whatsapp','Por WhatsApp','Enviadas al chat','chat'],['all','Todas','Radicadas en total','inbox']];
// Plazo de respuesta informado al paciente (24 h por defecto) contado desde la creación de la solicitud.
$slaHours=(int)$app->config['whatsapp_estimated_hours'];
$sla=function(array $row) use ($slaHours): array { $left=strtotime($row['created_at'])+$slaHours*3600-time(); $h=intdiv(abs($left),3600); $m=intdiv(abs($left)%3600,60);
  $exact=($h?$h.' h ':'').$m.' min'; $short=$h?$h.' h':$m.' min';
  if ($left<0) return ['late','Vencida','Vencida hace '.$short,'hace '.$exact]; return [$left<6*3600?'soon':'ok',$left<6*3600?'Por vencer':'A tiempo','Quedan '.$short,'quedan '.$exact]; }; ?>
<section class="card" id="deliveries"><h2 class="visually-hidden">Solicitudes</h2>
<nav class="status-cards" aria-label="Estado de las solicitudes"><?php foreach ($statusCards as [$cardFilter, $cardTitle, $cardText, $cardIcon]): $cardCount=(int)($deliveryCounts[$cardFilter] ?? 0); ?><a class="status-card <?= $cardFilter ?>" href="?page=deliveries&amp;f=<?= $cardFilter ?>" <?= $listFilter === $cardFilter ? 'aria-current="page"' : '' ?>><span class="status-card-title"><?= h($cardTitle) ?></span><strong class="status-card-count mono"><?= h(number_format($cardCount, 0, ',', '.')) ?></strong><span class="status-card-text"><?= h($cardText) ?></span><span class="status-card-icon" aria-hidden="true"><?= ui_icon($cardIcon, 20) ?></span></a><?php endforeach ?></nav>
<?php if ($deliverySearch['query'] === ''): ?><p class="muted status-cards-note"><?= ['pending' => 'Solicitudes sin historia enviada, de la más antigua a la más reciente. El paciente recibió un tiempo estimado de respuesta de ' . $slaHours . ' horas. Abre cada una para responder «Aprobado» (con los documentos) o «No Registra».', 'approved' => 'Historias validadas y con envío aceptado por el servidor de correo.' . ($isAdmin ? ' Si reabres un caso, vuelve a Pendientes hasta completar un nuevo envío.' : ''), 'not_registered' => 'Solicitudes respondidas «No Registra»: no hay historia clínica con los datos indicados.', 'whatsapp' => 'Historias y respuestas «Aprobado» enviadas al WhatsApp del paciente, de la más reciente a la más antigua, con el estado del último envío. «Automático» es la historia que el sistema envió solo al encontrarla o al cargar su PDF.', 'all' => 'Todas las solicitudes radicadas; las pendientes van primero.'][$listFilter] ?></p><?php endif ?>
<?php if ($pendingOnly && $deliverySearch['query'] === '' && ($oldest = $deliverySearch['rows'][0] ?? null)): ?><div class="queue-next"><a class="button primary" data-delivery-modal aria-haspopup="dialog" aria-controls="delivery-modal" href="?page=delivery&amp;id=<?= (int)$oldest['id'] ?>">Atender la más antigua <?= ui_icon('arrow-right', 18) ?></a></div><?php endif ?>
<p class="result-count" role="status"><strong class="mono"><?= (int)$deliverySearch['total'] ?></strong> solicitud(es)<?= $deliverySearch['query'] !== '' ? ' para «' . h($deliverySearch['query']) . '»' : '' ?>.</p>
<?php if (!$deliverySearch['rows']): ?><div class="empty-state"><?= ui_icon($pendingOnly && $deliverySearch['query'] === '' ? 'check-circle' : 'search', 28) ?><p><?= $pendingOnly && $deliverySearch['query'] === '' ? 'No hay solicitudes pendientes. Todas tienen historia enviada o una respuesta.' : ($isHistory ? 'No hay historias enviadas que coincidan con la búsqueda. Las entregas simuladas o fallidas no aparecen aquí.' : ($listFilter === 'not_registered' ? 'No hay solicitudes respondidas «No Registra» con esos datos.' : ($listFilter === 'whatsapp' ? 'No hay historias enviadas por WhatsApp que coincidan.' : 'No se encontraron solicitudes con esos datos. Prueba con parte del nombre, el radicado o el documento.'))) ?></p></div>
<?php else: ?>
<?php if ($isHistory): require __DIR__ . '/delivery-history-rows.php'; elseif ($listFilter === 'whatsapp'): require __DIR__ . '/whatsapp-sent-rows.php'; else: ?><div class="table-wrap"><table class="responsive-table requests-table" role="table"><thead role="rowgroup"><tr role="row"><th scope="col" role="columnheader">Paciente</th><th scope="col" role="columnheader">Radicado / fecha</th><th scope="col" role="columnheader">Contacto</th><th scope="col" role="columnheader">Estado</th><th scope="col" role="columnheader">Acciones</th></tr></thead><tbody role="rowgroup">
<?php foreach ($deliverySearch['rows'] as $row): ?><tr role="row" data-row-open><td role="cell" data-label="Paciente"><strong class="cell-name" title="<?= h($row['claimed_name']) ?>"><?= h($row['claimed_name']) ?></strong><?php if ($row['document_number']): ?><small class="cell-doc"><span class="doc-type"><?= h($row['document_type']) ?></span> <span class="mono"><?= h($row['document_number']) ?></span></small><?php else: ?><small>Documento no conservado</small><?php endif ?></td><td role="cell" data-label="Radicado / fecha"><strong class="mono ref"><?= h($row['reference']) ?></strong><small class="mono nowrap"><?= h(date('d/m/Y H:i', strtotime($row['created_at']))) ?></small></td><td role="cell" data-label="Contacto"><span class="cell-email" title="<?= h($row['contact_email'] ?? '') ?>"><?= h($row['contact_email'] ?? 'Sin correo') ?></span><?php if (!empty($row['whatsapp_phone'])): ?><small class="cell-channel"><?= ui_icon('chat', 14) ?>WhatsApp</small><?php endif ?></td><td role="cell" data-label="Estado"><div class="status-stack"><?php if ($pendingOnly): [$slaClass,$slaLabel,$slaText,$slaExact]=$sla($row); ?><span class="pill sla-<?= $slaClass ?>" title="<?= h($slaLabel . ': ' . $slaExact) ?>"><?= ui_icon($slaClass === 'late' ? 'alert' : 'clock', 14) ?><?= h($slaText) ?></span><?php endif ?><span class="pill <?= ui_tone($row['status']) ?>"><?= h($labels[$row['status']] ?? $row['status']) ?></span><?php if ($row['case_pending']): ?><span class="pill case-pending">Pendiente de gestión</span><small>Reabierto <?= h(date('d/m/Y H:i', strtotime($row['case_reopened_at']))) ?></small><?php endif ?><?php if ($row['last_error']): ?><small class="danger with-icon"><?= ui_icon('alert', 14) ?>Último envío con error</small><?php endif ?><small class="muted"><?= (int)$row['deliveries'] === 1 ? '1 envío' : (int)$row['deliveries'] . ' envíos' ?></small></div></td><td role="cell" data-label="Acciones"><div class="row-actions"><a class="history-button small" data-history-modal aria-haspopup="dialog" href="?page=case-history&amp;id=<?= (int)$row['id'] ?>" aria-label="Historial del caso <?= h($row['reference']) ?>" title="Historial del caso"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 12a9 9 0 1 0 3-6.7L3 8"/><path d="M3 3v5h5M12 7v5l3 2"/></svg></a><a class="button secondary eye-button" data-delivery-modal data-row-primary aria-haspopup="dialog" aria-controls="delivery-modal" href="?page=delivery&amp;id=<?= (int)$row['id'] ?>&amp;p=<?= (int)$deliverySearch['page'] ?>" aria-label="Ver solicitud <?= h($row['reference']) ?>" title="Ver y responder la solicitud"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></svg></a></div></td></tr><?php endforeach ?>
</tbody></table></div><?php endif ?>
<nav class="delivery-pagination" aria-label="Páginas de solicitudes"><?php if ($deliverySearch['page']>1): ?><a class="button secondary" href="?page=<?= $listPage ?><?= $filter ?>&amp;p=<?= $deliverySearch['page']-1 ?>"><?= ui_icon('arrow-left', 18) ?>Anterior</a><?php endif ?><span class="page-indicator">Página <strong class="mono"><?= (int)$deliverySearch['page'] ?></strong> de <span class="mono"><?= (int)$deliverySearch['pages'] ?></span></span><?php if ($deliverySearch['page']<$deliverySearch['pages']): ?><a class="button secondary" href="?page=<?= $listPage ?><?= $filter ?>&amp;p=<?= $deliverySearch['page']+1 ?>">Siguiente<?= ui_icon('arrow-right', 18) ?></a><?php endif ?></nav>
<?php endif ?></section>
<?php require __DIR__ . '/detail-modals.php'; ?>
<?php if ($isHistory && $isAdmin): ?>
<noscript><p class="muted">Sin JavaScript, «Reabrir» se aplica sin confirmación previa.</p></noscript>
<?php endif ?>
